import json, sys
for i, line in enumerate(open('$REEL/evidence/run-naive.jsonl')):
    try: obj = json.loads(line)
    except: continue
    t = obj.get('type', '?')
    subtype = obj.get('subtype', '')
    if t == 'system':
        print(f'[{i}] system {subtype}', obj.get('session_id',''))
    elif t == 'assistant':
        msg = obj.get('message', {})
        for c in msg.get('content', []):
            if c.get('type') == 'text':
                text = c.get('text','')[:400]
                print(f'[{i}] assistant text: {text}')
            elif c.get('type') == 'tool_use':
                name = c.get('name')
                inp = c.get('input', {})
                print(f'[{i}] assistant tool_use: {name}', json.dumps(inp)[:300])
    elif t == 'user':
        msg = obj.get('message', {})
        for c in msg.get('content', []):
            if c.get('type') == 'tool_result':
                content = c.get('content')
                if isinstance(content, list):
                    for item in content:
                        text = item.get('text','')[:200] if isinstance(item, dict) else str(item)[:200]
                        print(f'[{i}] tool_result:', text)
                else:
                    print(f'[{i}] tool_result:', str(content)[:200])
    elif t == 'result':
        print(f'[{i}] result: subtype={subtype} duration={obj.get(\"duration_ms\")} turns={obj.get(\"num_turns\")} cost={obj.get(\"total_cost_usd\")}')
        r = obj.get('result','')
        if r: print(f'   result text: {r[:400]}')
"

